    graph: { type: 'basis', title: 'Build a vector from two basis directions', sliders: [{ key: 'c1', label: 'c_1', min: -4, max: 4, step: 0.25, value: 2 }, { key: 'c2', label: 'c_2', min: -4, max: 4, step: 0.25, value: 1 }, { key: 'tilt', label: 'basis tilt', min: -2, max: 2, step: 0.25, value: 0.5 }] },
